	@Benchmark
	public long buildAndProbe(IndexCounters counters, Blackhole blackhole) throws IOException {
		OptionalCompatibilityIndex.Strategy selected = OptionalCompatibilityIndex.Strategy.valueOf(strategy);
		OptionalCompatibilityIndex index;
		long builtRows = 0L;
		try (OptionalCompatibilityIndex.Builder builder = builder(selected);
				RowCursor input = inputPlan.open(row)) {
			while (input.next()) {
				builder.appendCurrent(row);
				builtRows++;
			}
			index = builder.finish();
		}

		long accepted = 0L;
		long checksum = 1L;
		boolean spilled = index.spilled();
		try (index) {
			for (long probeKey : probeKeys) {
				row.replaceSlot(KEY_SLOT, probeKey);
				try (OptionalCompatibilityIndex.Probe probe = index.probe(row)) {
					while (probe.next()) {
						NativeResultRow candidate = probe.current();
						NativeResultCell candidateKey = candidate.cell(0);
						if (candidateKey.state() == NativeResultCell.State.BOUND
								&& !candidateKey.value().equals(values.get(probeKey))) {
							continue;
						}
						accepted++;
						for (int slot = 1; slot < slotCount; slot++) {
							Value payload = candidate.cell(slot).value();
							checksum = 31L * checksum + payload.hashCode();
							blackhole.consume(payload);
						}
						if ("first".equals(consumption)) {
							break;
						}
					}
				}
			}
			OptionalCompatibilityIndex.Metrics metrics = index.metrics();
			counters.record(metrics, builtRows, accepted, spilled);
		} finally {
			row.replaceSlot(KEY_SLOT, LmdbNativeAggregateCompiler.UNKNOWN);
		}
		return checksum ^ accepted;
	}

