	private void validateStrategiesAndSpillPolicy(int[] rightSlots) throws IOException {
		List<Map<List<Value>, Long>> commonResult = null;
		boolean expectedSpill = "spill".equals(storage);
		for (OptionalCompatibilityIndex.Strategy candidate : OptionalCompatibilityIndex.Strategy.values()) {
			OptionalCompatibilityIndex index;
			try (OptionalCompatibilityIndex.Builder builder = builder(candidate);
					RowCursor input = inputPlan.open(row)) {
				while (input.next()) {
					builder.appendCurrent(row);
				}
				index = builder.finish();
			}
			List<Map<List<Value>, Long>> results = new ArrayList<>(probeKeys.length);
			try (index) {
				if (index.spilled() != expectedSpill) {
					throw new IllegalStateException("Expected " + storage + " payload for " + size + "/" + width
							+ ", strategy=" + candidate + ", rows=" + index.size());
				}
				for (long probeKey : probeKeys) {
					row.replaceSlot(KEY_SLOT, probeKey);
					results.add(collectResultBag(index, probeKey));
				}
			} finally {
				row.replaceSlot(KEY_SLOT, LmdbNativeAggregateCompiler.UNKNOWN);
			}
			if (commonResult == null) {
				commonResult = results;
			} else if (!commonResult.equals(results)) {
				throw new IllegalStateException("Strategy bag mismatch: " + candidate + " returned a different exact"
						+ " per-probe bag for the matched probe sequence");
			}
		}
	}

	private OptionalCompatibilityIndex.Builder builder(OptionalCompatibilityIndex.Strategy selected) {
		return OptionalCompatibilityIndex.builder(row, rightSlots, sharedSlots, selected, null,
				selected == OptionalCompatibilityIndex.Strategy.AUTO ? autoDemand : null);
	}

	private Map<List<Value>, Long> collectResultBag(OptionalCompatibilityIndex index, long probeKey)
			throws IOException {
		Map<List<Value>, Long> result = new HashMap<>();
		Value expectedKey = values.get(probeKey);
		try (OptionalCompatibilityIndex.Probe probe = index.probe(row)) {
			while (probe.next()) {
				NativeResultRow candidate = probe.current();
				NativeResultCell candidateKey = candidate.cell(KEY_SLOT);
				if (candidateKey.state() == NativeResultCell.State.BOUND
						&& !candidateKey.value().equals(expectedKey)) {
					continue;
				}
				List<Value> mapping = new ArrayList<>(slotCount - 1);
				for (int slot = 1; slot < slotCount; slot++) {
					mapping.add(candidate.cell(slot).value());
				}
				result.merge(List.copyOf(mapping), 1L, Long::sum);
			}
		}
		return Map.copyOf(result);
	}

	private long term(Value value) {
		long id = values.size() + 1L;
		values.put(id, value);
		return id;
	}

